(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["ang"] = {"ui":{"skip":"Ġē tō þǣm inneweardan","back":"← Eft tō AI-gile","lang.button":"Spræċ: {name}","lang.dialog":"Cēos spræċe","lang.search":"Sēċ spræċa","lang.none":"Nān spræċ ne gedafenaþ","lang.notYet":"{name} nis nā ġȳt āwend","theme.aria":"Wend betwux lēohte and þēostre hīwe","theme.toLight":"Wend tō lēohtum hīwe","theme.toDark":"Wend tō þēostrum hīwe","index.title":"AI-gile: þīn AI-weorod, on ānum bord","index.description":"AI-gile is ċeartbord for AI-forgewrītena weorodu. Hīe wyrċaþ þonne þū slǣpst; þū hæfst ānne scortne hēap tō ġeċēosenne, tō costienne and tō onfōnne.","hero.logoAlt":"AI-gile bordes tācen","hero.h1.html":"Þīn AI-weorod, on ānum&nbsp;bord.","hero.alpha":"🐣 Belocen forme-alpha","hero.alphaTitle":"Ǣrlīċ and unġeendod: þancas þæt þū hit costast!","hero.lede":"Hīe timbriaþ þonne þū slǣpst. Þū onwæcnast tō ānum scortum hēape: sume ācsunga, sume dǣda tō costienne, ān oþþe twā purpuran ġimmas. Clyppa, onfōh, and eft tō þīnum drence.","dl.windows":"Windows-forgewrit","dl.browser":"Brūc hit on þīnum webseċende","dl.soon":"Sōna","dl.notify":"🔔 Cȳþ mē þonne hit openaþ","dl.notifySmall":"Alpha oþþe beta","hero.secondary":"Agile, ac þæt weorod ne þearf nǣfre stondende drenc. (Hīe dōþ stondende ġemōt þēah.)","pitch.h2":"AI-gile on swā manegum wordum swā þū wilt","pitch.lede":"Cēos lengþu, fram ānum worde tō 144. Ǣlc lengþu is hire āgen race, ġewriten for þā mǣþe. Teoh þone slīdend oþþe brūc þā strǣlcnappas.","pitch.rangeLabel":"Lengþu on wordum","pitch.dice":"🎲 ōþer ġewrit","pitch.words.one":"{n} word","pitch.words.other":"{n} word","pitch.letters.one":"{n} bōcstæf","pitch.letters.other":"{n} bōcstafas","pitch.chars.one":"{n} tācen","pitch.chars.other":"{n} tācn","count.line.html.one":"{n} ċeart on þǣm borde nū","count.line.html.other":"{n} ċearte on þǣm borde nū","features.aria":"Hwæt hit dēþ","f.pile.h":"Ān hēap for þē","f.pile.html":"<b>For þē</b> hielt eall þæt þē bīdaþ, ofer ǣlc weorc: ācsunga, þing tō costienne, weorc þe man ānīg dōn mæġ. Þīn ġerang segþ hwæt nēhst is and hū lang hit nimþ.","f.sleep.h":"Weorodu þe wyrċaþ þonne þū slǣpst","f.sleep.p":"Ǣlc weorc hæfþ ealdormann and weorod AI-sendan. Āwrīt word on ċearte and þæt weorod onwæcnaþ, dēþ þæt weorc, and bringþ hit eft mid stæpum þe wērig mann folgian mæġ.","f.tester.h":"AI-costere sceawaþ ǣrest","f.tester.p":"Ǣr þon þe ǣnig þing tō þē cymþ, folgaþ costere þǣm stæpum on onlīcnesse þæs forgewrites and æteawaþ hwæt hē ġeseah, mid sċērmmynde. Bēhwyrf þā forþfarenan and onfōh mid ānum clyppe.","f.proof.h":"Tācn, nā behāt","f.proof.p":"Ǣlc ofergifu æteawaþ hwæt wende: þā ġewritu, þone unġelīcnesse, þā sċērmmyndu. Nā þearft þū ǣlc forgewrit openian tō sēonne ġif hit gedōn is.","f.chat.h":"Sprec mid þīnum ealdormannum","f.chat.p":"Discord-lic sīdstrang: ān tācen for ǣlc weorc, purpuran ġimmas for þǣm þe þē þearf. Send ealdormenn ġeþōht; hē wyrcþ hit tō ċeartum and tō ġeþeahte, mid ✅ Fōr-cnappe.","f.tidy.h":"Hielt hit selfe clǣne","f.tidy.p":"Ġesibbe ċearte weorþaþ tō ānum, ġemenġede naman bēoþ ġerihte, and tācnes ġeseah hielt þone code smæl. Læsse tō wendenne, læsse tō þencenne.","f.private.h":"Þīn, on þīnum rīmcræfte","f.private.li1":"Þæt bord rint on þīnum āgenum tōle and andswarap ānum þē.","f.private.li2":"Dīgole ġewrit betwux mannum bēoþ fram ende tō ende ġehŷdde.","f.private.li3":"Nān ġerecen, nān fyligend, nān cȳcelċe.","f.lang.h":"On þīnre spræċe","f.lang.p":"Ofer 120 spræċa, fram Dyċe, Wēalisċre and Iēpānisċre tō wīċinge, Yoda and Klingon, mid fæstum wendunge eft tō Englisċ for þā wyrhtena word.","tl.aria":"Tīdlīne fram þǣre forman spræċe tō þǣre wegcarte","tl.h2":"Fram þǣre forman spræċe tō þǣm þe cymþ","tl.lede":"Sōþe dagas and tīda, on þīnre āgenre tīdsċīre. Æfter tōdæġ is hit þæt ġeþeaht, būtan behātenum dagum.","tl.today":"Tōdæġ","tl.planned":"ġeþeaht","tl.cards.one":"{n} ċeart","tl.cards.other":"{n} ċearte","join.h2":"Ġeþēod þē","join.lede":"AI-gile bið ġetimbrod fram lȳtlum menn and manegum þyldigum sendum. Hit is nū dīgol, on belocenum alpha mid frēondum. Wilt þū fandian þonne hit openaþ?","join.btn":"Āwrīt þīn willa","join.small":"Wē sendaþ þē ǣrendġewrit, nān ōþer þing","footer.tag":"AI-gile. Nān fyligend, nān cȳcelċe, nān stondende drenc.","footer.licence":"Cēapes lēafe","footer.status":"Stede","form.sending":"Sendende…","form.failed":"Þæt ne wyrċde: fand eft lǣtemest.","form.offline":"Ne mihte AI-gile ġerǣċan: fand eft lǣtemest.","interest.title":"AI-gile: cȳþ mē þonne se alpha openaþ","interest.description":"Læf þīn ǣrendġewrit tō ġehīrenne þonne AI-gile's belocen alpha oþþe beta openaþ.","interest.h1":"🔔 Cȳþ mē þonne hit openaþ","interest.lede":"AI-gile is on belocenum forme-alpha. Læf þīn ǣrendġewrit and wē āwrītaþ ānes, þonne stōw is for þē.","interest.email":"Þīn ǣrendġewrit","interest.which":"Hwilc costnung?","interest.alpha":"Belocen alpha: ǣrlīċ, rūh, fela wendunga","interest.beta":"Beta: fæstre, lǣtra","interest.both":"Swā hwæðer, swā hwæðer ǣr cymþ","interest.submit":"Sete mē on þā rīmcræft","interest.thanks":"Þancas! Þū eart on þǣre rīmcræfte.","interest.kept":"Ānīg þīn ǣrendġewrit and seo costnung þe þū cēose bēoþ ġehealdene, for þisse rīmcræfte ānum. Nān ǣrendbōc, nān fyligend.","licence.title":"AI-gile: cēapes lēafe","licence.description":"Brūcst þū AI-gile on þīnum cēape? Bidde frēo cēapes lēafe.","licence.h1":"📜 Cēapes lēafe","licence.lede":"Brūcst þū AI-gile æt weorce? Seċġ ūs hwā þū eart and hwæt þū dēst. Ġif hit hwæt gōdes dēþ, is seo lēafe frēo.","licence.company":"Weorod","licence.website":"Webstede","licence.what":"Hwæt þū dēst","licence.how":"Hū hit helpþ middanġearde","licence.email":"Ǣrendġewrit","licence.submit":"Bidde","licence.thanks":"Þancas! Wē andswariaþ mid ǣrendġewrite.","status.title":"AI-gile stede","status.h1":"AI-gile stede","status.quiet":"Eall cirm","status.checking":"Sċēawiende…","status.offline":"Ne mæġ nū þā stedeþēnunge ġerǣċan (eft fandiende)","status.updated":"nīwod {ago}","status.justNow":"nū þā","status.min":"{n} mīn ǣr","status.hours":"{n} h ǣr","status.days":"{n} d ǣr","live.h2":"Behald hit beon timbred, libbende","live.caption":"Ælc cræft is behydd: þu gesihst þæs weorces gescæp, na þa word.","live.watching.one":"libbende: {n} behealdað","live.watching.other":"libbende: {n} behealdað","live.offline":"Þæt libbende bord hæfþ ane hwile ēstes. Cum eft sōna.","live.cols":"Backlog|To donne|On weorce|Weorodes eahtung|For þē tō fandianne|For þǣm weorode|Gedōn","live.last.now":"Se ytemesta ċearta wearþ nū ġewend","live.last.min.one":"Se ytemesta ċearta wearþ ġewend ǣr {n} mynūte","live.last.min.other":"Se ytemesta ċearta wearþ ġewend ǣr {n} mynūtum","live.last.hour.one":"Se ytemesta ċearta wearþ ġewend ǣr {n} tīman","live.last.hour.other":"Se ytemesta ċearta wearþ ġewend ǣr {n} tīmum","live.last.day.one":"Se ytemesta ċearta wearþ ġewend ǣr {n} dæge","live.last.day.other":"Se ytemesta ċearta wearþ ġewend ǣr {n} dagum"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Ċeartbord.","Sendan.","Betæht."]},{"n":2,"texts":["Bord, sendan.","Sendan, ġeregnode.","Ġeþōhtas, ġetimbrode."]},{"n":3,"texts":["Ċeartbord for sendum.","Ġeþōhtas weorþaþ dǣda.","Frēo sendan-bord."]},{"n":5,"texts":["Ċeartbord þe sendan rǣdaþ.","Þū wrītst ċearte. Sendan timbriaþ.","Frēo, hēr, ġecostod, lȳtel dole."]},{"n":8,"texts":["Frēo ċeartbord þǣr AI-sendan weorc wyrċaþ.","Āwrīt ġeþōht. Sendan timbriaþ hit. Þū onfēhst.","Agile for ānum menn and manegum þyldigum sendum."]},{"n":13,"texts":["Ċeartbord on þīnum rīmcræfte þǣr AI-sendan þā ċearte nimaþ and wyrċaþ.","Āwrīt ġeþōht. Weorod sendena timbraþ hit. Costere sċēawaþ hit syþþan.","Frēo, nān ġerecen, nān fyligend: bord, sume sendan, and þū eart ealdor."]},{"n":21,"texts":["AI-gile is ċeartbord for weorce mid AI-forgewrītena sendum. Hīe nimaþ þā ċearte; þū costast and onfēhst hīe.","Ǣlc weorc hæfþ ealdormann and weorod AI-sendena. Āwrīt word on ǣniġe ċeart and þæt weorod onginþ wyrċan.","Frēo, āgen tōdōn-bord þe rint on þīnum āgenum rīmcræfte. Þā wyrhtan sind sendan. Se þe ġeþafaþ eart þū."]},{"n":34,"texts":["Þū settest ġeþōhtas on bord. Weorod AI-sendena went hīe tō wyrċendum dǣdum, costaþ hīe, and bringþ hīe eft mid stæpum tō fandienne. Nān þing ne ġelīcþ ġedōn oþ þū hit seċġst.","AI-gile is hāmġeworht ċeartbord þe Rich ġetimbrode mid micelre helpe þāra sendena þe hit nū rǣdaþ. Hit is frēo, rint on þīnum rīmcræfte, and bið ġedǣled mid frēondum, nā ġeseald for feo.","Ġeþenc ānfeald ċeartbord, mid rēawum fram Backlog tō Gedōn, būtan þæt AI-sendan nimaþ þā ċearte. Hīe cȳþaþ forþfaru, ācsiaþ þonne hīe fæste sind, and bīdaþ ǣfre þīnes lēafes."]},{"n":55,"texts":["AI-gile is ċeartbord þǣr þæt weorod is of AI-sendum ġemacod. Ǣlc weorc hæfþ ealdormann þe þæt weorc ġeþeahtaþ and helpan þe hit timbriaþ. Þonne dǣd gearu is, costaþ AI-costere hit and nimþ sċērmmynd, and siþþan cymþ hit tō þīnum hēape. Onfōh hit, oþþe āwrīt word and hīe eft wyrċaþ hit.","Hit onġann swā ānes mannes wīse tō healdenne fela AI-codes tīda æt ānum cierre, and weox tō rihtum borde. Hit rint on þīnum tōle, ne bidde nān ġerecen, and hæfþ nān fyligend. Hit is frēo for frēondum and ǣlcum þe ġīman wile. Hit is ēac unġeendod, forþȳ wēn rūhra ecga and hwīlum wundres.","Hēr is sēo sōþe race. Þū most ġȳt habban þā ġeþōhtas, and þū most ġȳt sċēawian þā ġeweorc. Hwæt AI-gile dēþ is eall þæt betweonan: hit hielt þā ċearte on endebyrdnesse, onwæcnaþ þone rihtan sendan þonne þū āwrītst word, æteawaþ ġenōg hwæt wende, and hielt eall on ānum scortum hēape for þē."]},{"n":89,"texts":["AI-gile is frēo ċeartbord þe þū rynst on þīnum āgenum rīmcræfte. For mannum hæfþ ǣlc weorc weorod AI-sendena: ealdormann þe wendþ þīne ġeþōhtas tō ċeartum and ġeþeahte, and helpan þe nimaþ þā ċearte on ġeendebyrdnesse. Þonne hwæt ġetimbrod is, folgaþ AI-costere þǣm costunge-stæpum and æteawaþ þē hwæt hē ġeseah. Þonne bīdaþ hit on ānum hēape ġemearcod For þē. Þū onfēhst hit, oþþe þū āwrītst word and þæt weorod fandaþ eft. Nān þing ne cymþ tō Gedōn būtan þē.","Sume þing þē ne wēnaþ. Nihtwæcce hielt þone rēaw To donne full þonne þū slǣpst, and cīesþ ċearte þe ne þurfon andsware fram þē. Tācnes-rīm æteawaþ hū fela þā sendan tōdæġ and þisse wucan brūcaþ, and Nān-Tācn-Wīse hǣtt hīe lētan ġewitan þone spendan. Þū miht ġewrītan frēondum, and dīgole ġewrit bēoþ fram ende tō ende ġehŷdde. Þæt bord sprecþ ymbe 120 spræċa, Dyċe, Flǣmisċ, wīċinga-spræċe and Klingon on þǣm. Nān þing hēr ne costaþ ānne pening, and nān mann ne wile hit sellan þē.","AI-gile is lȳtel āgen weorc, nā weorod cēapmanna. Rich wolde warian fela AI-codes weorca būtan ǣlc forgewrit tō openienne tō sēonne, forþȳ hē and þā sendan ġetimbredon bord for þǣm, and brūcon þæt bord tō timbrienne þone rest his selfes. Hit is on belocenum forme-alpha, þæt is, hit wyrċþ, swīþe, for hondfulle frēonda. Hēr is nān weorþ-bōc, nān ǣrendbōc and nān weaxan-ġeþeaht. Ġif hit þē nytt þynċþ, miht þū biddan tō fandienne þonne hit lȳtel openaþ furþor."]},{"n":144,"texts":["AI-gile is ċeartbord for ānum menn and fela AI-sendum. Hit rint on þīnum āgenum rīmcræfte and is eall frēo. Þū ēacast weorc, and ǣlc weorc ġet ealdormann and lȳtel weorod. Þū sprecst mid þǣm ealdormenn, swelċe on Discord, and āwrītst ġeþōht; se ealdormann wendþ hit tō ċeartum and tō ġeþeahte, and bīdaþ þæt þū clyppe Fōr. Þæt weorod wyrċþ þā ċearte on ġeendebyrdnesse þǣre mǣstan weorþnesse, mid ānfealdre hǣsstrīcan ġeworht for spræċ-bysnum. Ǣr ǣnig þing eft tō þē cymþ, folgaþ AI-costere þǣm stæpum on onlīcnesse þæs forgewrites and fæstnaþ sċērmmynd. Ġeendod weorc cymþ tō þīnum hēape mid þǣm wendum ġewritum and þǣm unġelīcnesse. Þū onfēhst hit, oþþe þū læfst word and þæt weorod onwæcnaþ and fandaþ eft. Ānīg þū miht ċeart tō Gedōn wendan.","Ān dæġ mid AI-gile, ġeneah. On ǣfen læfst þū sume word: þēos cnæpp is on wōhre stōwe, sēo ġerīm sċeal bēon ġesett, mihte wē habban þēostre wīse. Þū færst tō bedde. Þā sendan rǣdaþ þā word, dōþ þā wendunga, costaþ hīe and ġiefaþ hīe þē eft. Ġif To donne weorþeþ dryge, fylþ sēo nihtwæcce hit of þǣm backlog mid ċeartum þe ne þurfon andsware fram þē. On morgen is ān scort hēap: sume ācsunga and sume þing tō fandienne, ǣlc mid stæpum þe slǣpiġ mann folgian mæġ and sċērmmynd þæs hit wyrċþ. Þū clyppest þurh, onfēhst þā gōdan and sendst þā ōþre eft. Tācnes-rīm æteawaþ hwæt eall brūce, and Nān-Tācn-Wīse is for smalum wucum. Þonne ǣtst þū morgenmete, mid þǣm þā sendan ne magon ġȳt helpan.","Ǣrest, hwæt AI-gile nis. Hit nis nā cēapmanna weorod, hit nis tō sellanne, and nān mann ne ġaderaþ þīne ġewitu. Hit is frēo bord þe rint on þīnum rīmcræfte, būtan ġerecenum, fyligendum and cȳcelċum. Hwæt hit is: ān clǣne stōw tō sēonne ǣlc AI-codes weorc æt ānum cierre, mid weorode sendena þe dōþ þā ċearte and þē þe dēst þā dōmas. Hit fēgþ ġesibbe ċearte tōgædere, ġerihtaþ ġemenġede naman, and sċēawaþ hū smæl se code wunaþ. Hit sprecþ ymbe 120 spræċa, fram Dyċe and Flǣmiscre tō wīċinga-spræċe and Klingon. Frēond magon him ġewrītan, dīgollīċe and ġehŷdde. Hit wæs ġeworht fram Rich and fela þyldigum sendum, swīþost brūcende hit selfe. Hit is on belocenum forme-alpha, forþȳ hit is rūh on stōwum. Ġif hit þē wynsum þynċþ, bidde ġeornlīċe and þū miht ġǣdan on ǣrlīċe."]}],"quips":{"1":"Ān word. Hwæt. Mæġ tō hwæt.","3":"Þrēo word. Ġȳt sōþfæstra þonne fela cēapmanna sīdan.","8":"Eahta word. Ġȳt scortra þonne stondende ġemōt.","21":"Þā lengþa sind sāgan-pointas, ġeðēah. Hū ne?","55":"Fīf and fīftig worda. Twā ċearte wurdon ġeendode þā þū þis rǣdest.","144":"Þis is sēo lange. Nis nān 233. Þā sendan sind tō bedde ġewitene."}},"timeline":{"first-idea.name":"Se forma ġeþōht","first-idea.line":"Seo forme spræc, ǣr ǣnig code wæs.","first-board.name":"Forme bord","first-board.line":"Bord þe his āgen timbrunge tæcþ: ċearte, rēawas, tēon and drēopan, weorc.","team-roles.name":"Weorod and hādas","team-roles.line":"Sendan hīw, weoroda bysna, stōwa, and hwā hwæt dēþ.","install.name":"Onsetednes and ūtġifan","install.line":"Zip þe frēond onsettan mæġ, selfnīwung, wegas and eftwendan.","usage-saver.name":"Notu-sparian","usage-saver.line":"Mete hwæt rynas costaþ, hielt þone code smæl, spara þīn mearc.","friends.name":"Frēond and dǣlan","friends.line":"Dīgole ġewrit, ġehŷdd ġeġang, ġeladunga, hādas and ġedǣlde weorc.","languages.name":"Spræċa","languages.line":"Ǣlc sċērmword on spræċfile, mid Dyċe and Flǣmiscre ǣrest.","ai-tester.name":"AI-costere","ai-tester.line":"Costere sċēawaþ ǣlc ofergifu ǣrest and æteawaþ hwæt hē ġeseah.","website.name":"Se webstede","website.line":"aigile.lol, se teaser and þēos tīdlīne.","streaming.name":"Spræc and flōwan","streaming.line":"Discord, Twitch, OBS, flōwere-wīse, GIFs and emojis.","no-ai.name":"Būtan AI-ūtġifu","no-ai.line":"Bord for mannum þe codiaþ būtan AI, and openum bordum.","night-watch.name":"Nihtwæcce","night-watch.line":"Wæċċere and Scrum-lareow healdaþ þā weorodu æt weorce þonne þū slǣpst.","p-more.name":"Eall ōþer","p-more.line":"Smalran ġeþōhtas þe ġȳt bīdaþ hira tūrnes.","p-android.name":"Fōn and Android","p-android.line":"Ġerǣċ þīn bord fram fōne, siþþan āgen Android-forgewrit.","p-release.name":"Alpha and furþor","p-release.line":"Belocen alpha, se līfiġenda stede, siþþan beta.","p-languages.name":"Māran spræċa","p-languages.line":"Māre þonne hund spræċa, and ġedīpung-wīse for leorneras.","p-engines.name":"Māran AI-ġinnas","p-engines.line":"Cēos Claude, Codex oþþe Gemini for ǣlcum sendan.","p-pro.name":"Cræftiġ brūcung","p-pro.line":"Frēcnes tācn, ġeþēodnes ġeatu, ġelimp-ċearte and wearnunga.","p-self.name":"Cēping þīn","p-self.line":"Wērig-wīse, selfcēping ġemynd and 4:20.","p-servers.name":"Þēnas and mǣþ","p-servers.line":"Eallworuldlice þēnas ġesetnessa, hādas and ġeþeaht for weaxan.","p-livestream.name":"Flōwan-ēacan","p-livestream.line":"Twitch-spræc, āgene emojis and openlic līf-sċēawung."}};
